insert into dp_content_private.review_queue(question_id,severity,reason,state,evidence) values('CAPF_2025_P1_105','CRITICAL','Published final key 105=2 (B), agreeing with the existing chemistry explanation. No historical attempts at verification.','RESOLVED','{"paper_url": "https://cdn.aglasem.com/aglasem-doc/2a7ea460-8ce1-11f1-9c3b-0aa932765c8b/2a7ea460-8ce1-11f1-9c3b-0aa932765c8b.pdf", "paper_sha256": "938a640529ea2f53109cd8e7b397460b2abb6e616cdec7e77920e0b2f5fa34b8", "booklet": "FKKB-O-GAIT/39A", "key_url": "https://www.upsc.gov.in/sites/default/files/AnsKey-CAPFACs-Exam-2025-GAI-110826.pdf", "key_page": 1, "key_method": "Visual inspection of UPSC final key Set A; numeric 1/2/3/4 = A/B/C/D, asterisk = dropped. Printed question and all options visually matched.", "printed_page": 43, "source_question": 105, "reason": "Published final key 105=2 (B), agreeing with the existing chemistry explanation. No historical attempts at verification."}'::jsonb) on conflict(question_id) do update set severity=excluded.severity,reason=excluded.reason,state=excluded.state,evidence=excluded.evidence,updated_at=now();
