insert into dp_content_private.review_queue(question_id,severity,reason,state,evidence) values('CAPF_2025_P1_108','CRITICAL','Published final key 108=4 (D). Stored official A and final C disagree. Option D says minimum energy while explanation describes energy loss; withhold pending subject adjudication, do not silently change scoring to an educationally disputed answer.','OPEN','{"paper_url": "https://cdn.aglasem.com/aglasem-doc/2a7ea460-8ce1-11f1-9c3b-0aa932765c8b/2a7ea460-8ce1-11f1-9c3b-0aa932765c8b.pdf", "paper_sha256": "938a640529ea2f53109cd8e7b397460b2abb6e616cdec7e77920e0b2f5fa34b8", "booklet": "FKKB-O-GAIT/39A", "key_url": "https://www.upsc.gov.in/sites/default/files/AnsKey-CAPFACs-Exam-2025-GAI-110826.pdf", "key_page": 1, "key_method": "Visual inspection of UPSC final key Set A; numeric 1/2/3/4 = A/B/C/D, asterisk = dropped. Printed question and all options visually matched.", "printed_page": 45, "source_question": 108, "reason": "Published final key 108=4 (D). Stored official A and final C disagree. Option D says minimum energy while explanation describes energy loss; withhold pending subject adjudication, do not silently change scoring to an educationally disputed answer."}'::jsonb) on conflict(question_id) do update set severity=excluded.severity,reason=excluded.reason,state=excluded.state,evidence=excluded.evidence,updated_at=now();
